begin;
create temporary table p2p_test_context(key text primary key,value text);
grant all on p2p_test_context to authenticated;
insert into p2p_test_context values('user_a',gen_random_uuid()::text),('user_b',gen_random_uuid()::text);
insert into auth.users(id,email,raw_user_meta_data,created_at,updated_at)select value::uuid,value||'@example.invalid','{}'::jsonb,now(),now() from p2p_test_context;
select set_config('request.jwt.claims',json_build_object('sub',(select value from p2p_test_context where key='user_a'),'role','authenticated')::text,true);
set local role authenticated;
do $$
declare first_device jsonb;second_device jsonb;signal_id uuid;expired_device jsonb;
begin
 first_device:=public.create_pairing('P2P test PC','Windows desktop');second_device:=public.create_pairing('P2P test phone','Android phone');
 if public.authorize_peer((first_device->>'device_id')::uuid,(second_device->>'device_id')::uuid) then raise exception 'Unapproved devices authorized';end if;
 perform public.join_pairing(first_device->>'code',(second_device->>'device_id')::uuid);perform public.confirm_pairing(first_device->>'code');
 if not public.authorize_peer((first_device->>'device_id')::uuid,(second_device->>'device_id')::uuid) then raise exception 'Approved peers rejected';end if;
 begin perform public.confirm_pairing(first_device->>'code');raise exception 'Consumed code accepted';exception when raise_exception then if sqlerrm<>'Pairing expired or unavailable' then raise;end if;end;
 signal_id:=public.send_rtc_signal((first_device->>'device_id')::uuid,(second_device->>'device_id')::uuid,gen_random_uuid(),'hello','{}'::jsonb);
 if not exists(select 1 from public.rtc_signals where id=signal_id) then raise exception 'Signal not readable';end if;
 begin perform public.send_rtc_signal((first_device->>'device_id')::uuid,(second_device->>'device_id')::uuid,gen_random_uuid(),'hello','{"text":"must not upload"}'::jsonb);raise exception 'Clipboard payload accepted';exception when raise_exception then if sqlerrm<>'Hello must not contain data' then raise;end if;end;
 begin perform public.send_clip((first_device->>'device_id')::uuid,'must not upload',false,7);raise exception 'Legacy upload still granted';exception when insufficient_privilege then null;end;
 insert into p2p_test_context values('first',first_device->>'device_id'),('second',second_device->>'device_id'),('signal',signal_id::text);
 update public.devices set revoked=true where id=(second_device->>'device_id')::uuid;
 if public.authorize_peer((first_device->>'device_id')::uuid,(second_device->>'device_id')::uuid) then raise exception 'Revoked peer authorized';end if;
 if exists(select 1 from public.rtc_signals) then raise exception 'Revoked peer metadata exposed';end if;
 begin perform public.send_rtc_signal((first_device->>'device_id')::uuid,(second_device->>'device_id')::uuid,gen_random_uuid(),'hello','{}'::jsonb);raise exception 'Revoked signal accepted';exception when raise_exception then if sqlerrm<>'Device authorization rejected' then raise;end if;end;
 expired_device:=public.create_pairing('Expired pairing test','Another browser');
 insert into p2p_test_context values('expired_device',expired_device->>'device_id'),('expired_code',expired_device->>'code');
end $$;
reset role;
update public.pairings set expires_at=now()-interval '1 second' where initiator=(select value::uuid from p2p_test_context where key='expired_device');
set local role authenticated;
do $$begin
 begin perform public.confirm_pairing((select value from p2p_test_context where key='expired_code'));raise exception 'Expired pairing confirmed';exception when raise_exception then if sqlerrm<>'Pairing expired or unavailable' then raise;end if;end;
 begin perform public.join_pairing((select value from p2p_test_context where key='expired_code'),(select value::uuid from p2p_test_context where key='first'));raise exception 'Expired pairing joined';exception when raise_exception then if sqlerrm<>'Code expired, already requested, or unavailable' then raise;end if;end;
end $$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select value from p2p_test_context where key='user_b'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin if exists(select 1 from public.rtc_signals) or public.authorize_peer((select value::uuid from p2p_test_context where key='first'),(select value::uuid from p2p_test_context where key='second')) then raise exception 'Cross-account signaling exposed';end if;end $$;
reset role;
update public.devices set revoked=false where id=(select value::uuid from p2p_test_context where key='second');
update public.rtc_signals set expires_at=now()-interval '1 second' where id=(select value::uuid from p2p_test_context where key='signal');
select set_config('request.jwt.claims',json_build_object('sub',(select value from p2p_test_context where key='user_a'),'role','authenticated')::text,true);
set local role authenticated;
do $$begin if exists(select 1 from public.rtc_signals)then raise exception 'Expired signal exposed';end if;end $$;
reset role;
rollback;
select 'P2P pairing expiration, signaling authorization, revocation, replay expiry, payload restrictions, and legacy upload rejection passed; all test data rolled back.' as result;
